#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAXN 100005
#define LOG 18

int N, Q;
int p[MAXN];
int tin[MAXN], tout[MAXN], rev[MAXN];
int head[MAXN], to[MAXN], nxt[MAXN];
int edge_cnt = 0;
int bit[MAXN];
int up[LOG][MAXN];

void add(int idx, int delta) {
    while (idx <= N) {
        bit[idx] += delta;
        idx += idx & -idx;
    }
}

int sum(int idx) {
    int res = 0;
    while (idx > 0) {
        res += bit[idx];
        idx -= idx & -idx;
    }
    return res;
}

int find_kth(int k) {
    int idx = 0;
    int bitmask = 1;
    while (bitmask << 1 <= N) bitmask <<= 1;
    for (; bitmask; bitmask >>= 1) {
        int next = idx + bitmask;
        if (next <= N && bit[next] < k) {
            idx = next;
            k -= bit[next];
        }
    }
    return idx + 1;
}

int kth_ancestor(int u, int k) {
    for (int j = 0; j < LOG; j++) {
        if (k & (1 << j)) {
            u = up[j][u];
        }
    }
    return u;
}

int main() {
    scanf("%d", &N);
    p[1] = 0;
    for (int i = 2; i <= N; i++) {
        scanf("%d", &p[i]);
    }

    // Build children list
    for (int i = 1; i <= N; i++) head[i] = -1;
    for (int i = 2; i <= N; i++) {
        to[edge_cnt] = i;
        nxt[edge_cnt] = head[p[i]];
        head[p[i]] = edge_cnt++;
    }

    // Iterative DFS for Euler tour
    int stack[MAXN], state[MAXN];
    int top = 0;
    stack[top] = 1; state[1] = 0; top++;
    int timer = 0;
    while (top > 0) {
        int u = stack[top-1];
        if (state[u] == 0) {
            tin[u] = ++timer;
            rev[timer] = u;
            state[u] = 1;
            for (int e = head[u]; e != -1; e = nxt[e]) {
                int v = to[e];
                stack[top] = v;
                state[v] = 0;
                top++;
            }
        } else {
            tout[u] = timer;
            top--;
        }
    }

    // Binary lifting
    for (int i = 1; i <= N; i++) up[0][i] = p[i];
    for (int j = 1; j < LOG; j++) {
        for (int i = 1; i <= N; i++) {
            up[j][i] = up[j-1][ up[j-1][i] ];
        }
    }

    memset(bit, 0, sizeof(bit));

    scanf("%d", &Q);
    while (Q--) {
        int type;
        scanf("%d", &type);
        if (type == 1) {
            int v, k;
            scanf("%d %d", &v, &k);
            int cnt = sum(tin[v] - 1);
            int u = 0;
            if (cnt > 0) {
                int idx = find_kth(cnt);
                u = rev[idx];
                if (tout[u] >= tin[v]) {
                    // u is proper marked ancestor
                    if (k == 1) {
                        printf("%d\n", u);
                    } else {
                        int ans = kth_ancestor(u, k-1);
                        printf("%d\n", ans);
                    }
                    continue;
                }
            }
            int ans = kth_ancestor(v, k);
            printf("%d\n", ans);
        } else {
            int v;
            scanf("%d", &v);
            int cnt = sum(tin[v] - 1);
            if (cnt > 0) {
                int idx = find_kth(cnt);
                int u = rev[idx];
                if (tout[u] >= tin[v]) {
                    // has proper marked ancestor, do nothing
                    continue;
                }
            }
            // remove all marked nodes in subtree(v)
            while (1) {
                int cnt_before = sum(tin[v] - 1);
                int next_k = cnt_before + 1;
                int total = sum(N);
                if (next_k > total) break;
                int idx = find_kth(next_k);
                int w = rev[idx];
                if (tin[w] <= tout[v]) {
                    add(tin[w], -1);
                } else {
                    break;
                }
            }
            add(tin[v], 1);
        }
    }
    return 0;
}
